try: if schedule == "exited": # Real command EOF and exit, observed without collecting the pinned child. os.close(worker.command) worker.channels.remove(worker.command) worker.command = None end = time.monotonic() + 1 # WNOWAIT leaves the exit status waitable for the runtime's first check. # https://docs.python.org/3/library/os.html#os.WNOWAIT while time.monotonic() < end: exited = os.waitid(os.P_PID, pid, os.WNOHANG | os.WEXITED | os.WNOWAIT) if exited is not None and exited.si_pid == pid: break time.sleep(0.001) else: pytest.fail("fixture did not enter real waitable exited state") elif schedule == "stopped": real_kill(pid, signal.SIGSTOP) end = time.monotonic() + 1 while time.monotonic() < end: waited, status = real_waitpid(pid, os.WNOHANG | os.WUNTRACED) if waited == pid and os.WIFSTOPPED(status): break time.sleep(0.001) else: pytest.fail("fixture did not enter real stopped state")
deadline = time.monotonic() - 0.01 with monkeypatch.context() as runtime: runtime.setattr(os, "waitpid", waitpid) runtime.setattr(os, "fork", forbidden) runtime.setattr(os, "kill", forbidden) runtime.setattr(os, "killpg", forbidden) receipt = worker_capture.capture_helper(("/usr/bin/true",), deadline, worker=worker) before_audit = worker.evidence() retain(tmp_path, f"persistent-expired-request-{schedule}", receipt) assert receipt.error and worker.failure and worker.closed assert len(calls) == 1 assert calls[0]["pid"] == pid and calls[0]["flags"] == os.WNOHANG assert calls[0]["entered"] >= deadline collected = calls[0]["result"][0] == pid assert owner.reaped is collected assert owner.reap_attempts == 1 if schedule != "natural": assert collected is (schedule == "exited") assert bool(worker.evidence()["residual_remedy"]) is not collected assert bool(receipt.residual_remedy) is not collected assert worker.start() is False second = worker_capture.capture_helper( ("/usr/bin/true",), time.monotonic() + 0.5, worker=worker ) assert second.error and second.pid is None and second.worker is None worker.close() worker.close() worker_capture._reap(owner) worker_capture._signal(owner, signal.SIGTERM) worker_capture._signal(owner, signal.SIGKILL) > assert len(calls) == 1 E AssertionError: assert 2 == 1 E + where 2 = len([{'pid': 56343, 'flags': 1, 'entered': 357803.151726125, 'result': (0, 0)}, {'pid': 56343, 'flags': 1, 'entered': 357803.16256325, 'result': (0, 0)}])
